// Funci�n para calcular el porcentaje de refuerzo basado en luminosity_real
function calcularRefuerzo(lux) {
    if (lux < 500) {
        return 100;
    } else if (lux < 1500) {
        return 50 + (100 - 50) * (1500 - lux) / (1500 - 500);
    } else if (lux < 3000) {
        return 25 + (50 - 25) * (3000 - lux) / (3000 - 1500);
    } else if (lux < 5000) {
        return (25 * (5000 - lux)) / (5000 - 3000);
    } else {
        return 0;
    }
}

